#!/usr/bin/env bash
# playtest: (x1,y1)→(x2,y2) 드래그. begin/drag(5단계)/end 디스패치. Play Mode 필요.
set -euo pipefail
X1="$1"; Y1="$2"; X2="$3"; Y2="$4"
UEXEC="$(cd "$(dirname "$0")/../../unity-editor-ops/scripts" && pwd)/uexec.sh"
CODE="var es = UnityEngine.EventSystems.EventSystem.current; if (es == null) return \"NO_EVENTSYSTEM\"; var ped = new UnityEngine.EventSystems.PointerEventData(es){ position = new UnityEngine.Vector2($X1,$Y1) }; var res = new System.Collections.Generic.List<UnityEngine.EventSystems.RaycastResult>(); es.RaycastAll(ped, res); if (res.Count == 0) return \"NO_HIT\"; var go = res[0].gameObject; ped.pointerCurrentRaycast = res[0]; ped.pointerPressRaycast = res[0]; var h = UnityEngine.EventSystems.ExecuteEvents.GetEventHandler<UnityEngine.EventSystems.IDragHandler>(go); if (h == null) h = go; UnityEngine.EventSystems.ExecuteEvents.Execute(go, ped, UnityEngine.EventSystems.ExecuteEvents.pointerDownHandler); UnityEngine.EventSystems.ExecuteEvents.Execute(h, ped, UnityEngine.EventSystems.ExecuteEvents.beginDragHandler); for (int i = 1; i <= 5; i++) { ped.position = UnityEngine.Vector2.Lerp(new UnityEngine.Vector2($X1,$Y1), new UnityEngine.Vector2($X2,$Y2), i / 5f); UnityEngine.EventSystems.ExecuteEvents.Execute(h, ped, UnityEngine.EventSystems.ExecuteEvents.dragHandler); } UnityEngine.EventSystems.ExecuteEvents.Execute(h, ped, UnityEngine.EventSystems.ExecuteEvents.endDragHandler); UnityEngine.EventSystems.ExecuteEvents.Execute(go, ped, UnityEngine.EventSystems.ExecuteEvents.pointerUpHandler); return \"OK drag \" + go.name;"
"$UEXEC" "$CODE"
